import React, { useState } from 'react';

const Register = () => {
  const [step, setStep] = useState(1);
  const [submitted, setSubmitted] = useState(false);
  
  // Regroupement de toutes les données saisies
  const [formData, setFormData] = useState({
    email: '', password: '', firstName: '', lastName: '', country: '', phone: ''
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  if (submitted) return <div className="p-20 text-center text-emerald-500 font-mono">✓ VÉRIFIEZ VOTRE BOÎTE MAIL POUR ACTIVER VOTRE COMPTE.</div>;

  return (
    <div className="max-w-md mx-auto p-8 bg-slate-950 border border-slate-900 mt-10">
      {step === 1 ? (
        <div className="space-y-4">
          <button className="w-full bg-white text-slate-950 py-2 uppercase text-[10px] font-bold">Continuer avec Google</button>
          <input name="email" type="email" placeholder="Email" onChange={handleChange} className="w-full bg-slate-900 p-2 text-white border border-slate-800" />
          <input name="password" type="password" placeholder="Mot de passe" onChange={handleChange} className="w-full bg-slate-900 p-2 text-white border border-slate-800" />
          
          {/* Jauge de sécurité */}
          <div className="h-1 bg-slate-900 w-full">
            <div className={`h-full ${formData.password.length > 8 ? 'bg-emerald-500' : 'bg-red-500'}`} 
                 style={{width: `${Math.min(formData.password.length * 10, 100)}%`}}></div>
          </div>
          <button onClick={() => setStep(2)} className="w-full bg-blue-600 text-white py-2 uppercase text-[10px]">Suivant</button>
        </div>
      ) : (
        <div className="space-y-4">
          <input name="firstName" type="text" placeholder="Prénom" onChange={handleChange} className="w-full bg-slate-900 p-2 text-white border border-slate-800" />
          <input name="lastName" type="text" placeholder="Nom" onChange={handleChange} className="w-full bg-slate-900 p-2 text-white border border-slate-800" />
          <input name="country" type="text" placeholder="Pays" onChange={handleChange} className="w-full bg-slate-900 p-2 text-white border border-slate-800" />
          <input name="phone" type="tel" placeholder="Téléphone" onChange={handleChange} className="w-full bg-slate-900 p-2 text-white border border-slate-800" />
          <button onClick={() => setSubmitted(true)} className="w-full bg-emerald-600 text-white py-2 uppercase text-[10px]">Créer le compte</button>
        </div>
      )}
    </div>
  );
};
export default Register;
